const items = $input.all();

return items.map((item) => {
  const json = item.json;
  const nomeCompleto = (json.from && json.from.value && json.from.value[0] && json.from.value[0].name) || '';
  const email = (json.from && json.from.value && json.from.value[0] && json.from.value[0].address) || json.from || '';
  const assunto = json.subject || '';
  const mensagem = json.textPlain || json.text || '';

  const partesNome = nomeCompleto.trim().split(/\s+/).filter(Boolean);
  const firstname = partesNome[0] || '';
  const lastname = partesNome.slice(1).join(' ');

  return {
    json: {
      firstname,
      lastname,
      email,
      assunto,
      mensagem,
      data: json.date || new Date().toISOString()
    }
  };
});
